<script setup lang="ts">import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import BrandLogo from'@/components/common/BrandLogo.vue';import{useCafe}from'@/stores/cafe';import{num}from'@/utils/format';const store=useCafe(),router=useRouter(),scanning=ref(false);onMounted(()=>{store.load()});function scan(){if(scanning.value)return;scanning.value=true;setTimeout(()=>router.push({name:'menu',query:{table:store.table}}),2000)}</script><template><section class="qr-screen"><BrandLogo/><div class="qr-card"><h2>اطلب من طاولتك 📱</h2><p>امسح رمز الـ QR بالأسفل لبدء تصفح المنيو والطلب مباشرة</p><div class="qr-frame"><span class="corner tl"/><span class="corner tr"/><span class="corner bl"/><span class="corner br"/><div class="qr-laser" :class="{animating:scanning}"/><img class="qr-code-svg" src="/qr-code.svg" alt="QR"></div><div id="scanStatus" aria-live="polite">{{scanning?'📷 جاري مسح رمز الـ QR...':'رمز الطاولة جاهز للمسح'}}</div></div><div class="table-sel-wrap"><label>رقم الطاولة الافتراضي:</label><div class="table-sel-grid"><button v-for="t in store.db.tables.filter(x=>x.on)" :key="t.id" class="table-sel-btn" :class="{sel:store.table===t.n}" @click="store.setTable(t.n)">{{t.name || `طاولة ${num(t.n)}`}}</button></div></div><button class="qr-btn" :disabled="scanning" @click="scan">{{scanning?'جاري المسح...':'▣ محاكاة مسح الكود بالكاميرا'}}</button></section></template>
